import {Config, Field, Query} from 'alinea'

export const BlogPost = Config.document('Blog post', {
  fields: {
    cover: Field.image('Cover'),
    category: Field.entry('Category', {condition: {_type: 'Category'}}),
    publishDate: Field.date('Publish date')
  }
})

export const Blog = Config.document('Blog', {
  contains: ['BlogPost'],
  fields: {},
  overview: {
    columns: {
      cover: Config.column({
        header: 'Cover',
        width: 72,
        select: BlogPost.cover
      }),
      category: Config.column({
        header: 'Category',
        select: BlogPost.category,
        sortBy: BlogPost.category.first({select: Query.title})
      }),
      publishDate: Config.column({
        header: 'Published',
        width: 140,
        select: BlogPost.publishDate
      })
    },
    sort: {desc: BlogPost.publishDate},
    layout: 'cards',
    thumbnail: BlogPost.cover
  }
})

import {Config} from 'alinea'
import {productsOverview} from '@/schema/Product'

export const products = Config.root('Products', {
  contains: ['Product'],
  overview: productsOverview
})

import {Config, Field, type OverviewOptions, Query} from 'alinea'

export const Product = Config.document('Product', {
  fields: {
    articleNumber: Field.text('Article number'),
    categories: Field.entry.multiple('Categories', {
      condition: {_type: 'Category'}
    }),
    brand: Field.entry('Brand', {condition: {_type: 'Brand'}}),
    price: Field.number('Price'),
    stock: Field.number('Stock')
  }
})

export const productsOverview: OverviewOptions = {
  columns: {
    articleNumber: Config.column({
      header: 'Article number',
      width: 140,
      select: Product.articleNumber,
      position: 'start'
    }),
    categories: Config.column({
      header: 'Categories',
      select: Product.categories.find({
        select: {entryId: Query.id, title: Query.title},
        filter: {_status: 'published'},
        orderBy: {asc: Query.title}
      })
    }),
    brand: Config.column({
      header: 'Brand',
      select: Product.brand,
      sortBy: Product.brand.first({select: Query.title})
    }),
    price: Config.column({
      header: 'Price',
      width: 120,
      align: 'end',
      select: Product.price,
      format: (price, {locale}) =>
        typeof price === 'number'
          ? new Intl.NumberFormat(locale ?? 'en', {
              style: 'currency',
              currency: 'EUR'
            }).format(price)
          : ''
    }),
    stock: Config.column({
      header: 'Stock',
      width: 120,
      select: Product.stock,
      view: '@/views/StockCell#StockCell'
    })
  },
  builtins: {updated: false},
  actions: ['@/views/ExportProducts#ExportProducts']
}

import type {OverviewCellProps} from 'alinea/cms'
import {Badge} from 'alinea/components'

export function StockCell({value}: OverviewCellProps<number | null>) {
  if (typeof value !== 'number') return null
  return <Badge>{value > 0 ? `${value} in stock` : 'Sold out'}</Badge>
}

import {Config, Field, Query} from 'alinea'

export const Article = Config.document('Article', {
