  contains: ['Article', 'Event'],
  fields: {},
  overview: {
    columns: {
      person: Config.column({
        header: 'Author or organiser',
        select: {Article: Article.author, Event: Event.organiser},
        sortBy: {
          Article: Article.author.first({select: Query.title}),
          Event: Event.organiser.first({select: Query.title})
        }
