import {Query} from 'alinea'
import {type OverviewActionProps, useGraph} from 'alinea/cms'
import {Button} from 'alinea/components'
import {Product} from '@/schema/Product'

export function ExportProducts({query}: OverviewActionProps) {
  const graph = useGraph()
  async function exportCsv() {
    const rows = await graph.find({
      ...query,
      select: {
        title: Query.title,
        articleNumber: Product.articleNumber,
        price: Product.price
      }
    })
    const csv = rows
      .map(row => [row.title, row.articleNumber, row.price].join(';'))
      .join('\n')
    const link = document.createElement('a')
    link.href = URL.createObjectURL(new Blob([csv], {type: 'text/csv'}))
    link.download = 'products.csv'
    link.click()
  }
  return (
    <Button variant="outline" onClick={exportCsv}>
      Export
    </Button>
  )
}

import {Config, Field} from 'alinea'

export const Brand = Config.document('Brand', {
  fields: {
    logo: Field.image('Logo'),
    ...Field.view('@/views/BrandProducts#BrandProducts')
  }
})

import {EntryTable, useEntry} from 'alinea/cms'
import {Field} from 'alinea/components'
import {Product, productsOverview} from '@/schema/Product'

export function BrandProducts() {
  const entry = useEntry()
  if (!entry) return null
  return (
    <Field label="Products">
      <EntryTable
        aria-label="Products"
        type={Product}
        overview={productsOverview}
        filter={{brand: {has: {_entry: entry.id}}}}
        emptyMessage="No products for this brand yet"
      />
    </Field>
  )
}

import {Config} from 'alinea'
import {IcReport} from '@/icons'

export const reports = Config.root('Reports', {
  icon: IcReport,
  view: '@/views/Reports#Reports'
})

import {EntryTable, type RootViewProps} from 'alinea/cms'
import {Heading, Text} from 'alinea/components'
import {Product} from '@/schema/Product'

export function Reports({root}: RootViewProps) {
  return (
    <>
      <Heading>{root.label}</Heading>
      <Text>Products that are out of stock</Text>
      <EntryTable
        aria-label="Sold out products"
        type={Product}
        filter={{stock: 0}}
        emptyMessage="Everything is in stock"
      />
    </>
  )
}
